60	static mi_decl_noinline mi_theap_t* mi_heap_init_theap(const mi_heap_t* const_heap)
61	{
62	  mi_heap_t* heap = (mi_heap_t*)const_heap;
63	  mi_assert_internal(heap!=NULL);
64	
65	  // initialize thread first in case this is the main heap
66	  // (which may allocate the default theap already for the main heap)
67	  if (!_mi_thread_is_initialized()) {
68	    mi_thread_init();
69	  }
70	
71	  // get the thread local theap
72	  mi_theap_t* theap = (mi_theap_t*)_mi_thread_local_get(heap->theap);
73	
74	  // create a fresh theap?
75	  if (theap==NULL) {
76	    // allocate a fresh theap
77	    theap = _mi_theap_create(heap, mi_theap_get_default()->tld); // sets the theap thread local
78	    if (theap==NULL) {
79	      _mi_error_message(EFAULT, "unable to allocate memory for a thread local heap\n");
80	      return NULL;
81	    }
82	    _mi_heap_theap_set(heap, theap);
83	    mi_assert_internal(theap == (mi_theap_t*)_mi_thread_local_get(heap->theap));
84	  }
85	  return theap;
86	}
