93	  mi_theap_t* theap = (mi_theap_t*)_mi_thread_local_get(heap->theap);
94	  if mi_unlikely(theap==NULL) {
95	    theap = mi_heap_init_theap(heap);
96	    if (theap==NULL) { return (mi_theap_t*)&_mi_theap_empty_wrong; }  // this will return NULL from page.c:_mi_malloc_generic
97	  }
98	  _mi_theap_cached_set(theap);
99	  return theap;
100	}
