102	void _mi_heap_init(mi_heap_t* heap, mi_thread_local_t theap_slot, mi_subproc_t* subproc, mi_arena_id_t exclusive_arena_id)
103	{
104	  // init fields
105	  heap->theap = theap_slot;
106	  heap->subproc = subproc;
107	  heap->heap_seq = mi_atomic_increment_relaxed(&subproc->heap_total_count);
108	  heap->exclusive_arena = _mi_arena_from_id(exclusive_arena_id);
109	  heap->numa_node = -1; // no initial affinity
110	  mi_stats_header_init(&heap->stats);
111	  mi_lock_init(&heap->theaps_lock);
112	  mi_lock_init(&heap->os_abandoned_pages_lock);
113	  mi_lock_init(&heap->arena_pages_lock);
114	
115	  // push onto the subproc heaps
116	  mi_lock(&heap->subproc->heaps_lock) {
117	    mi_heap_t* head = heap->subproc->heaps;
118	    heap->prev = NULL;
119	    heap->next = head;
120	    if (head!=NULL) { head->prev = heap;  }
121	    heap->subproc->heaps = heap;
122	  }
123	  mi_atomic_increment_relaxed(&subproc->heap_count);
124	  mi_subproc_stat_increase(subproc, heaps, 1);
125	  mi_assert_internal(_mi_is_heap_main(heap) ? heap->theap == mi_thread_local_key_fast : heap->theap != 0);
126	}
