128	mi_heap_t* _mi_heap_new_for_subproc(mi_subproc_t* subproc, mi_arena_id_t exclusive_arena_id, bool is_main_heap) {
129	  mi_assert_internal(is_main_heap ? (subproc->heap_main == NULL && subproc->parent != NULL) : subproc->heap_main != NULL);
130	  // heap data is allocated in the current subproc
131	  mi_heap_t* const heap_main = (is_main_heap ? subproc->parent->heap_main : subproc->heap_main);
132	  // todo: allocate heap data in the exclusive arena ?
133	  mi_heap_t* const heap = (mi_heap_t*)mi_heap_zalloc( heap_main, sizeof(mi_heap_t) );
134	  if (heap==NULL) return NULL;
135	  // reserve a thread local slot for this heap (see also issue #1230)
136	  mi_thread_local_t theap_slot = (is_main_heap ? mi_thread_local_key_fast : _mi_thread_local_create());
137	  if (theap_slot == 0) {
138	    _mi_error_message(EFAULT, "unable to dynamically create a thread local for a heap\n");
139	    mi_free(heap);
140	    return NULL;
141	  }
142	  if (is_main_heap) {
143	    mi_assert_internal(subproc->heap_main == NULL);
144	    subproc->heap_main = heap;
145	  }
146	  _mi_heap_init(heap, theap_slot, subproc, exclusive_arena_id);
147	  return heap;
148	}
