152	  // main heap does not exist yet and `_mi_heap_new_for_subproc` would allocate from a NULL `subproc->heap_main`.
153	  mi_thread_init();
154	  return _mi_heap_new_for_subproc(_mi_subproc(), exclusive_arena_id, false);
