161	// free all theaps belonging to this heap (without deleting their pages as we do this arena wise for efficiency)
162	static void mi_heap_free_theaps(mi_heap_t* heap) {
163	  // This can run concurrently with a thread that terminates (see `init.c:mi_thread_theaps_done`),
164	  // and we need to ensure we free theaps atomically.
165	
166	  // We first detach our theaps list from any thread local lists
167	  _mi_heap_detach_theaps(heap);
168	
169	  // Now we can safely free the theaps
170	  mi_lock(&heap->theaps_lock) { // paranoia
171	    mi_theap_t* theap = heap->theaps;
172	    heap->theaps = NULL;
173	    while(theap != NULL) {
174	      mi_theap_t* next = theap->hnext;
175	      theap->hnext = NULL;
176	      theap->hprev = NULL;
177	      mi_assert_internal(theap->tld==NULL);
178	      // merge stats into the owning heap stats
179	      _mi_stats_merge_into(&heap->stats, &theap->stats);
180	      // and free
181	      _mi_theap_decref(theap);  // a cached entry can still point to the theap
182	      theap = next;
183	    }
184	  }  
185	}
186	
187	// free the heap resources (assuming the pages are already moved/destroyed, and all theaps have been freed)
188	static void mi_heap_free(mi_heap_t* heap, bool acquire_heaps_lock) {
189	  mi_assert_internal(heap!=NULL); // && !_mi_is_process_heap_main(heap));
190	
191	  // free all arena pages infos
192	  const bool is_main = _mi_is_heap_main(heap);
193	  if (!is_main) {  // pages for the main heap are pre-allocated in the arenas
194	    mi_lock(&heap->arena_pages_lock) {
195	      for (size_t i = 0; i < MI_MAX_ARENAS; i++) {
196	        mi_arena_pages_t* arena_pages = mi_atomic_load_ptr_relaxed(mi_arena_pages_t, &heap->arena_pages[i]);
197	        if (arena_pages!=NULL) {
198	          mi_atomic_store_ptr_relaxed(mi_arena_pages_t, &heap->arena_pages[i], NULL);
199	          _mi_free_subproc_safe(arena_pages);
200	        }
201	      }
202	    }
203	  }
204	
205	  // remove the heap from the subproc
206	  if (!is_main) { 
207	    mi_heap_stats_merge_to_main(heap); 
208	  }
209	  else {
210	    _mi_stats_merge_into(&heap->subproc->stats,&heap->stats);
211	  }
212	  mi_atomic_decrement_relaxed(&heap->subproc->heap_count);
213	  mi_subproc_stat_decrease(heap->subproc, heaps, 1);
214	  mi_lock_maybe(&heap->subproc->heaps_lock, acquire_heaps_lock) {
215	    if (heap->next!=NULL) { heap->next->prev = heap->prev; }
216	    if (heap->prev!=NULL) { heap->prev->next = heap->next; }
217	                     else { heap->subproc->heaps = heap->next; }
218	  }
219	
220	  mi_lock_done(&heap->theaps_lock);
221	  mi_lock_done(&heap->os_abandoned_pages_lock);
222	  mi_lock_done(&heap->arena_pages_lock);
223	  if (!_mi_is_process_heap_main(heap)) { 
224	    _mi_thread_local_free(heap->theap);
225	    _mi_free_subproc_safe(heap); 
226	  }
227	}
228	
229	void mi_heap_delete(mi_heap_t* heap) {
230	  if (heap==NULL) return;
231	  mi_heap_t* heap_main = mi_heap_get_heap_main(heap);
232	  if (heap == heap_main) {
233	    _mi_warning_message("cannot delete the main heap\n");
234	    return;
235	  }
236	  mi_heap_free_theaps(heap);
237	  _mi_heap_move_pages(heap, heap_main);
238	  mi_heap_free(heap,true /* acquire subproc->heaps_lock */);
239	}
240	
241	void _mi_heap_force_destroy(mi_heap_t* heap, bool acquire_heaps_lock) {
242	  if (heap==NULL) return;
243	  mi_heap_free_theaps(heap);
244	  _mi_heap_destroy_pages(heap);
245	  // if (_mi_subproc_main()->heap_main == heap) {
246	  //   _mi_stats_merge_into(&heap->subproc->stats,&heap->stats);
247	  // }
248	  // else 
249	  {
250	    mi_heap_free(heap, acquire_heaps_lock);   // todo: release locks of the main heap?  
251	  }
252	}
253	
254	void mi_heap_destroy(mi_heap_t* heap) {
255	  if (heap==NULL) return;
256	  if (_mi_is_heap_main(heap)) {
257	    _mi_warning_message("cannot destroy the main heap\n");
258	    return;
259	  }
260	  _mi_heap_force_destroy(heap,true /* acquire subproc->heaps_lock */);
261	}
262	
263	mi_heap_t* mi_heap_of(const void* p) {
264	  mi_page_t* const page = _mi_safe_ptr_page(p);
265	  if (page==NULL) return NULL;
266	  return mi_page_heap(page);
267	}
268	
269	bool mi_any_heap_contains(const void* p) {
270	  mi_page_t* const page = _mi_safe_ptr_page(p);
271	  return (page!=NULL);
272	}
273	
274	bool mi_heap_contains(const mi_heap_t* heap, const void* p) {
275	  if (heap==NULL) { heap = mi_heap_main(); }
276	  return (heap==mi_heap_of(p));
277	}
278	
279	// deprecated
280	bool mi_check_owned(const void* p) {
281	  return mi_any_heap_contains(p);
282	}
283	
284	// unsafe heap utilization function for DragonFly (see issue #1258)
285	// If the page of pointer `p` belongs to `heap` (or `heap==NULL`) and has less than `perc_threshold` used blocks in its used area return `true`.
286	// This function is unsafe in general as it assumes we are the only thread accessing the page of `p`.
287	bool mi_unsafe_heap_page_is_under_utilized(mi_heap_t* heap, void* p, size_t perc_threshold) mi_attr_noexcept {
288	  if (p==NULL) return false;
289	  const mi_page_t* const page = _mi_safe_ptr_page(p);   // Get the page containing this pointer
290	  if (page==NULL || page->used==page->capacity || page->capacity < page->reserved) return false;
291	  // If the page is the head of the queue, it is currently being used for
292	  // allocations; we skip it to avoid immediate thrashing.
293	  if (page->prev == NULL)  return false;
294	
295	  // match heap?
296	  const mi_heap_t* const page_heap = mi_page_heap(page);
297	  if (page_heap==NULL) return false;
298	  if (heap!=NULL && page_heap!=heap) return false;
299	
300	  // check utilization
301	  if (page->capacity==0)   return false;
302	  if (perc_threshold>=100) return true;
303	  return (perc_threshold >= ((100UL*page->used) / page->capacity));
304	}
