24	// Visit all pages in a theap; returns `false` if break was called.
25	static bool mi_theap_visit_pages(mi_theap_t* theap, theap_page_visitor_fun* fn, bool include_full, void* arg1, void* arg2)
26	{
27	  if (theap==NULL || theap->page_count==0) return true;
28	
29	  // visit all pages
30	  #if MI_DEBUG>1
31	  size_t total = theap->page_count;
32	  size_t count = 0;
33	  #endif
34	
35	  const size_t max_bin = (include_full ? MI_BIN_FULL : MI_BIN_FULL - 1);
36	  for (size_t i = 0; i <= max_bin; i++) {
37	    mi_page_queue_t* pq = &theap->pages[i];
38	    mi_page_t* page = pq->first;
39	    while(page != NULL) {
40	      mi_page_t* next = page->next; // save next in case the page gets removed from the queue
41	      mi_assert_internal(mi_page_theap(page) == theap);
42	      #if MI_DEBUG>1
43	      count++;
44	      #endif
45	      if (!fn(theap, pq, page, arg1, arg2)) return false;
46	      page = next; // and continue
47	    }
48	  }
49	  mi_assert_internal(!include_full || count == total);
50	  return true;
51	}
