97	static bool mi_theap_page_collect(mi_theap_t* theap, mi_page_queue_t* pq, mi_page_t* page, void* arg_collect, void* arg2 ) {
98	  MI_UNUSED(arg2);
99	  MI_UNUSED(theap);
100	  mi_assert_expensive(mi_theap_page_is_valid(theap, pq, page, NULL, NULL));
101	  mi_collect_t collect = *((mi_collect_t*)arg_collect);
102	  _mi_page_free_collect(page, collect >= MI_FORCE);
103	  if (mi_page_all_free(page)) {
104	    // no more used blocks, possibly free the page.
105	    if (collect >= MI_FORCE || page->retire_expire == 0) {  // either forced/abandon, or not already retired
106	      // note: this will potentially free retired pages as well.
107	      _mi_page_free(page, pq);
108	    }
109	  }
110	  else if (collect == MI_ABANDON) {
111	    // still used blocks but the thread is done; abandon the page
112	    _mi_page_abandon(page, pq);
113	  }
114	  return true; // don't break
