414	// Remove the theaps in this thread from the heaps that own them.
415	void _mi_tld_detach_theaps( mi_tld_t* tld ) {
416	  bool all_detached;
417	  do {
418	    all_detached = true;
419	    mi_lock(&tld->theaps_lock) {
420	      mi_theap_t* theap = tld->theaps;
421	      while (theap != NULL) {
422	        mi_theap_t* next = theap->tnext;
423	        mi_assert_internal(theap->page_count==0);
424	        mi_heap_t* heap = _mi_theap_heap_peek(theap); // now the heap might be NULL from an earlier iteration
425	        if (heap != NULL) {
426	          if (mi_lock_try_acquire(&heap->theaps_lock)) {
427	            // merge stats into the owning heap stats
428	            _mi_stats_merge_into(&heap->stats, &theap->stats);
429	            // remove the theap from the heap list
430	            if (theap->hnext != NULL) { theap->hnext->hprev = theap->hprev; }
431	            if (theap->hprev != NULL) { theap->hprev->hnext = theap->hnext; }
432	                                else { mi_assert_internal(heap->theaps == theap); heap->theaps = theap->hnext; }
433	            theap->hnext = theap->hprev = NULL;
434	            // and set `heap` to NULL
435	            mi_atomic_store_ptr_release(mi_heap_t, &theap->heap, NULL);
436	            mi_lock_release(&heap->theaps_lock);
437	          }
438	          else {
439	            all_detached = false;
440	          }
441	        }
442	        theap = next;
443	      }
444	    }
445	    if (!all_detached) {
446	      mi_subproc_stat_counter_increase(tld->subproc,heaps_delete_wait,1);
447	      _mi_prim_thread_yield();
448	    }
449	  } while (!all_detached);
450	}
