541	
542	void _mi_heap_area_init(mi_heap_area_t* area, mi_page_t* page) {
543	  const size_t bsize = mi_page_block_size(page);
544	  const size_t ubsize = mi_page_usable_block_size(page);
545	  area->reserved = page->reserved * bsize;
546	  area->committed = page->capacity * bsize;
547	  area->blocks = mi_page_start(page);
548	  area->used = page->used;   // number of blocks in use (#553)
549	  area->block_size = ubsize;
550	  area->full_block_size = bsize;
551	  area->reserved1 = page;
552	}
553	
554	static void mi_get_fast_divisor(size_t divisor, uint64_t* magic, size_t* shift) {
555	  mi_assert_internal(divisor > 0 && divisor <= UINT32_MAX);
556	  *shift = MI_SIZE_BITS - mi_clz(divisor - 1);
557	  *magic = ((((uint64_t)1 << 32) * (((uint64_t)1 << *shift) - divisor)) / divisor + 1);
558	}
559	
560	static size_t mi_fast_divide(size_t n, uint64_t magic, size_t shift) {
561	  mi_assert_internal(n <= UINT32_MAX);
562	  const uint64_t hi = ((uint64_t)n * magic) >> 32;
563	  return (size_t)((hi + n) >> shift);
564	}
565	
566	bool _mi_theap_area_visit_blocks(const mi_heap_area_t* area, mi_page_t* page, mi_block_visit_fun* visitor, void* arg) {
567	  mi_assert(area != NULL);
568	  if (area==NULL) return true;
569	  mi_assert(page != NULL);
570	  if (page == NULL) return true;
571	
572	  _mi_page_free_collect(page,true);              // collect both thread_delayed and local_free
573	  mi_assert_internal(page->local_free == NULL);
574	  if (page->used == 0) return true;
575	
576	  size_t psize;
577	  uint8_t* const pstart = mi_page_area(page, &psize);
578	  mi_heap_t* const heap = mi_page_heap(page);
579	  const size_t bsize    = mi_page_block_size(page);
580	  const size_t ubsize   = mi_page_usable_block_size(page); // without padding
581	
582	  // optimize page with one block
583	  if (page->capacity == 1) {
584	    mi_assert_internal(page->used == 1 && page->free == NULL);
585	    return visitor(heap, area, pstart, ubsize, arg);
586	  }
587	  mi_assert(bsize <= UINT32_MAX);
588	
589	  // optimize full pages
590	  if (page->used == page->capacity) {
591	    uint8_t* block = pstart;
592	    for (size_t i = 0; i < page->capacity; i++) {
593	      if (!visitor(heap, area, block, ubsize, arg)) return false;
594	      block += bsize;
595	    }
596	    return true;
597	  }
598	
599	  // create a bitmap of free blocks.
600	  #define MI_MAX_BLOCKS   (MI_SMALL_PAGE_SIZE / sizeof(void*))
601	  uintptr_t free_map[MI_MAX_BLOCKS / MI_INTPTR_BITS];
602	  const uintptr_t bmapsize = _mi_divide_up(page->capacity, MI_INTPTR_BITS);
603	  memset(free_map, 0, bmapsize * sizeof(intptr_t));
604	  if (page->capacity % MI_INTPTR_BITS != 0) {
605	    // mark left-over bits at the end as free
606	    size_t shift   = (page->capacity % MI_INTPTR_BITS);
607	    uintptr_t mask = (UINTPTR_MAX << shift);
608	    free_map[bmapsize - 1] = mask;
609	  }
610	
611	  // fast repeated division by the block size
612	  uint64_t magic;
613	  size_t   shift;
614	  mi_get_fast_divisor(bsize, &magic, &shift);
615	
616	  #if MI_DEBUG>1
617	  size_t free_count = 0;
618	  #endif
619	  for (mi_block_t* block = page->free; block != NULL; block = mi_block_next(page, block)) {
620	    #if MI_DEBUG>1
621	    free_count++;
622	    #endif
623	    mi_assert_internal((uint8_t*)block >= pstart && (uint8_t*)block < (pstart + psize));
624	    size_t offset = (uint8_t*)block - pstart;
625	    mi_assert_internal(offset % bsize == 0);
626	    mi_assert_internal(offset <= UINT32_MAX);
627	    size_t blockidx = mi_fast_divide(offset, magic, shift);
628	    mi_assert_internal(blockidx == offset / bsize);
629	    mi_assert_internal(blockidx < MI_MAX_BLOCKS);
630	    size_t bitidx = (blockidx / MI_INTPTR_BITS);
631	    size_t bit = blockidx - (bitidx * MI_INTPTR_BITS);
632	    free_map[bitidx] |= ((uintptr_t)1 << bit);
633	  }
634	  mi_assert_internal(page->capacity == (free_count + page->used));
635	
636	  // walk through all blocks skipping the free ones
637	  #if MI_DEBUG>1
638	  size_t used_count = 0;
639	  #endif
640	  uint8_t* block = pstart;
641	  for (size_t i = 0; i < bmapsize; i++) {
642	    if (free_map[i] == 0) {
643	      // every block is in use
644	      for (size_t j = 0; j < MI_INTPTR_BITS; j++) {
645	        #if MI_DEBUG>1
646	        used_count++;
647	        #endif
648	        if (!visitor(heap, area, block, ubsize, arg)) return false;
649	        block += bsize;
650	      }
651	    }
652	    else {
653	      // visit the used blocks in the mask
654	      uintptr_t m = ~free_map[i];
655	      while (m != 0) {
656	        #if MI_DEBUG>1
657	        used_count++;
658	        #endif
659	        size_t bitidx = mi_ctz(m);
660	        if (!visitor(heap, area, block + (bitidx * bsize), ubsize, arg)) return false;
661	        m &= m - 1;  // clear least significant bit
662	      }
663	      block += bsize * MI_INTPTR_BITS;
664	    }
665	  }
666	  mi_assert_internal(page->used == used_count);
667	  return true;
668	}
