509	  callback_t* callbacks = (callback_t*)custom_calloc(nthreads,sizeof(callback_t));
510	  thandles[0] = GetCurrentThread(); // avoid lint warning
511	  const size_t start = (main_participates ? 1 : 0);
512	  for (size_t i = start; i < nthreads; i++) {
513	    callbacks[i].fun = fun;
514	    callbacks[i].tid = i;
515	    callbacks[i].arg = arg;
516	    callbacks[i].subproc = subproc;
517	    thandles[i] = CreateThread(0, 8*1024L, &win_thread_entry, (void*)&callbacks[i], 0, &tids[i]);
518	  }
519	  if (main_participates) {
520	    fun(0,arg); // run the main thread as well
521	  }
522	  for (size_t i = start; i < nthreads; i++) {
523	    WaitForSingleObject(thandles[i], INFINITE);
524	  }
525	  for (size_t i = start; i < nthreads; i++) {
526	    CloseHandle(thandles[i]);
527	  }
